  /** 그룹 멤버를 order 순으로 반환 */
  const orderedGroupMembers = (groupId: string): ModuleInstance[] =>
    modules.value.filter((m) => m.groupId === groupId).sort((a, b) => a.order - b.order)

  /** 멤버들의 rowIndex/columnIndex로부터 행별 컬럼 수 배열을 유도 */
  const deriveRowsFromMembers = (members: ModuleInstance[]): number[] => {
    const rowCount = Math.max(1, ...members.map((m) => (m.rowIndex ?? 0) + 1))
    const rows = Array.from({ length: rowCount }, () => 1)
    for (const m of members) {
      const r = Math.min(Math.max(m.rowIndex ?? 0, 0), rowCount - 1)
      rows[r] = Math.max(rows[r], clampColumns((m.columnIndex ?? 0) + 1))
    }
    return rows
  }

  /**
   * [행별 컬럼] 레거시(group.columns + fullWidth) 그룹을 행별 독립 컬럼 모델로 승격한다.
   * group.rows가 이미 있으면 아무것도 하지 않는다. (읽기 경로는 항상 신모델을 가정)
   */
  const ensureGroupRows = (group: ModuleGroup): void => {
    if (group.rows && group.rows.length > 0) return
    const members = orderedGroupMembers(group.id)
    const res = resolveGroupRows(group, members)
    members.forEach((m) => {
      m.rowIndex = res.rowIndexById[m.id] ?? 0
      m.columnIndex = res.colIndexById[m.id] ?? 0
      delete m.fullWidth
    })
    group.rows = res.rowCols.length > 0 ? res.rowCols : [1]
    delete group.columns
  }

  /**
   * [행별 컬럼] 선택 모듈이 속한 '행'에 컬럼을 하나 추가한다(그 행만 +1단, 최대 4).
   * - 그룹에 없으면: 그 모듈만으로 1행짜리 그룹을 만든 뒤 그 행을 2단으로.
   * @returns 그 행의 적용된 컬럼 수 (실패 시 null)
   */
  const splitModuleColumns = (moduleId: string): number | null => {
    const mod = modules.value.find((m) => m.id === moduleId)
    if (!mod) return null

    let groupId = mod.groupId
    if (!groupId) {
      const gid = createGroup([moduleId]) // 단독 모듈 → 1행(1컬럼) 그룹
      if (!gid) return null
      groupId = gid
    }
    const group = groups.value.find((g) => g.id === groupId)
    if (!group) return null
    ensureGroupRows(group)
    const rows = group.rows as number[]
    const r = Math.min(Math.max(mod.rowIndex ?? 0, 0), rows.length - 1)
    const next = clampColumns(rows[r] + 1)
    if (next === rows[r]) return rows[r]
    rows[r] = next
    // 그 행 멤버 중 컬럼 인덱스 미지정은 0으로 확정
    modules.value.forEach((m) => {
      if (m.groupId === groupId && (m.rowIndex ?? 0) === r && m.columnIndex == null) m.columnIndex = 0
    })
    triggerRef(groups)
    triggerRef(modules)
    selectedGroupId.value = null
    isDirty.value = true
    return next
  }

  /**
   * [행별 컬럼] 선택 모듈이 속한 '행'의 컬럼을 하나 줄인다(-1단).
   * - 사라지는 마지막 컬럼의 모듈들은 그 행의 마지막 남는 컬럼으로 합쳐진다.
   * - 그룹이 1행·1컬럼·단일 멤버가 되면 그룹까지 해제(완전 원복).
   * @returns 그 행의 되돌린 뒤 컬럼 수 (실패 시 null)
   */
  const unsplitModuleColumns = (moduleId: string): number | null => {
    const mod = modules.value.find((m) => m.id === moduleId)
    if (!mod || !mod.groupId) return null
    const group = groups.value.find((g) => g.id === mod.groupId)
    if (!group) return null
    ensureGroupRows(group)
    const rows = group.rows as number[]
    const r = Math.min(Math.max(mod.rowIndex ?? 0, 0), rows.length - 1)
    const cur = rows[r]
    if (cur <= 1) return cur
    const next = cur - 1

    // 이 행에서 사라지는 컬럼(next 이상)의 모듈을 마지막 남는 컬럼(next-1)으로 클램프
    modules.value.forEach((m) => {
      if (m.groupId === group.id && (m.rowIndex ?? 0) === r && (m.columnIndex ?? 0) > next - 1) {
        m.columnIndex = next - 1
      }
    })
    rows[r] = next

    // 그룹이 1행·1컬럼·단일 멤버로 축소되면 그룹 해제(완전 원복)
    const members = orderedGroupMembers(group.id)
    if (rows.length === 1 && rows[0] === 1 && members.length <= 1) {
      members.forEach((m) => {
        delete m.groupId
        delete m.rowIndex
        delete m.columnIndex
      })
      const gi = groups.value.findIndex((g) => g.id === group.id)
      if (gi !== -1) groups.value.splice(gi, 1)
      if (selectedGroupId.value === group.id) selectedGroupId.value = null
      triggerRef(groups)
      triggerRef(modules)
      isDirty.value = true
      return 1
    }
    triggerRef(groups)
    triggerRef(modules)
    isDirty.value = true
    return next
  }

  /**
   * [행별 컬럼] 특정 행의 특정 컬럼(주로 빈 컬럼)을 삭제한다.
   * - 삭제 컬럼보다 오른쪽 컬럼들은 왼쪽으로 한 칸 당겨진다.
   * - 삭제 컬럼에 모듈이 남아 있으면 왼쪽 컬럼으로 흡수된다.
   * @returns 삭제 후 그 행의 컬럼 수 (실패 시 null)
   */
  const removeColumn = (groupId: string, rowIndex: number, columnIndex: number): number | null => {
    const group = groups.value.find((g) => g.id === groupId)
    if (!group) return null
    ensureGroupRows(group)
    const rows = group.rows as number[]
    if (rowIndex < 0 || rowIndex >= rows.length) return null
    const cols = rows[rowIndex]
    if (cols <= 1) return cols
    const next = cols - 1

    // 이 행에서 삭제 컬럼 오른쪽은 왼쪽으로 당기고, 삭제 컬럼의 잔여 모듈은 왼쪽 컬럼으로 흡수
    modules.value.forEach((m) => {
      if (m.groupId !== groupId || (m.rowIndex ?? 0) !== rowIndex) return
      const c = m.columnIndex ?? 0
      if (c > columnIndex) m.columnIndex = c - 1
      else if (c === columnIndex) m.columnIndex = Math.max(columnIndex - 1, 0)
    })
    rows[rowIndex] = next

    // 삭제한 컬럼이 추가 대상이었다면 해제
    if (columnTarget.value?.groupId === groupId) columnTarget.value = null
    triggerRef(groups)
    triggerRef(modules)
    isDirty.value = true
    return next
  }

  /**
   * [행별 컬럼] 빈 컬럼을 '추가 대상'으로 지정 (다음에 추가되는 모듈이 이 행/컬럼으로).
   * 캔버스 '직접 구성' 버튼이 호출한다 — 좌측 패널을 이 컬럼의 '구성 요소' 패널로 전환하기 위해
   * 기존 선택(다른 컬럼의 모듈 등)과 레일 패널 고정을 함께 해제한다.
   */
  const setColumnTarget = (groupId: string, rowIndex: number, columnIndex: number): void => {
    columnTarget.value = { groupId, rowIndex, columnIndex }
    selectedModuleId.value = null
    selectedGroupId.value = null
    useEditorStore().forceRailPanel = false
  }
  /** [행별 컬럼] 추가 대상 컬럼 지정 해제 */
  const clearColumnTarget = (): void => {
    columnTarget.value = null
  }

  /**
   * [행별 컬럼] 같은 행 이웃 컬럼의 모듈을 복제해 대상(빈) 컬럼을 채운다.
   * 대상보다 왼쪽에서 가장 가까운 컬럼(없으면 가장 왼쪽 컬럼)의 멤버들을 복제한다.
   */
  const duplicateIntoColumn = (groupId: string, rowIndex: number, columnIndex: number): void => {
    const rowMembers = modules.value.filter(
      (m) => m.groupId === groupId && (m.rowIndex ?? 0) === rowIndex,
    )
    if (rowMembers.length === 0) return
    const cols = Array.from(new Set(rowMembers.map((m) => m.columnIndex ?? 0)))
    const leftCols = cols.filter((c) => c < columnIndex).sort((a, b) => b - a)
    const sourceCol = leftCols.length > 0 ? leftCols[0] : Math.min(...cols)
    const sources = rowMembers.filter((m) => (m.columnIndex ?? 0) === sourceCol)
    if (sources.length === 0) return

    const lastIdx = modules.value.map((m) => m.groupId).lastIndexOf(groupId)
    const clones: ModuleInstance[] = sources.map((m) => ({
      ...m,
      id: generateUniqueId('module'),
      rowIndex,
      columnIndex,
      properties: JSON.parse(JSON.stringify(m.properties)),
      styles: JSON.parse(JSON.stringify(m.styles)),
    }))
    modules.value.splice(lastIdx + 1, 0, ...clones)
    reorderModules()
    selectedModuleId.value = clones[0].id
    columnTarget.value = null
    isDirty.value = true
  }

  // ===== [행별 컬럼] 구성 요소(조립 원소) 토글 — Figma 717-9607 =====
  // 나눈 컬럼(셀)을 이미지·타이틀·텍스트·버튼 원소로 구성한다. 체크=존재, 해제=제거.
  // (조립형 02와 동일한 원소 매핑. 타이틀/텍스트는 둘 다 ModuleDescText라 __composedKind로 구분)
  const COMPOSED_SPECS: Record<ComposedKind, { moduleId: string; overrides: Record<string, unknown> }> = {
    image: { moduleId: 'ModuleImg', overrides: {} },
    title: {
      moduleId: 'ModuleDescText',
      overrides: {
        descriptionText:
          '<p style="margin:0; padding:0; line-height:1.7;"><strong style="font-size:22px;">타이틀을 입력하세요</strong></p>',
        textColor: '#111111',
      },
    },
    text: {
      moduleId: 'ModuleDescText',
      overrides: {
        descriptionText: '<p style="margin:0; padding:0; line-height:1.7;">본문 텍스트를 입력하세요.</p>',
      },
    },
    button: { moduleId: 'ModuleOneButton', overrides: { buttonText: '자세히 보기 →' } },
    // 작은 버튼(옆으로 나열, 최대 4개) — 모듈 기본값(버튼 1개 노출)을 그대로 쓴다
    smallButton: { moduleId: 'ModuleSmallButton', overrides: {} },
  }

  // 셀(그룹/행/컬럼) 멤버 — order 기준 정렬
  const cellMembers = (groupId: string, rowIndex: number, columnIndex: number): ModuleInstance[] =>
    modules.value
      .filter(
        (m) =>
          m.groupId === groupId && (m.rowIndex ?? 0) === rowIndex && (m.columnIndex ?? 0) === columnIndex,
      )
      .sort((a, b) => a.order - b.order)

  // 모듈 → 구성 요소 종류 판별 (타이틀/텍스트는 __composedKind로, 없으면 텍스트로 간주)
  const moduleComposedKind = (m: ModuleInstance): ComposedKind | null => {
    if (m.moduleId === 'ModuleImg') return 'image'
    if (m.moduleId === 'ModuleOneButton') return 'button'
    if (m.moduleId === 'ModuleSmallButton') return 'smallButton'
    if (m.moduleId === 'ModuleDescText')
      return m.properties.__composedKind === 'title' ? 'title' : 'text'
    return null
  }

  /**
   * 셀 안의 구성 요소 목록 — 실제 배치 순서(위→아래)대로, 종류당 하나(첫 번째)만.
   * 구성 요소 4종에 해당하지 않는 모듈(구분선 등)과 같은 종류의 중복 모듈은 제외된다.
   */
  const columnElements = (
    groupId: string,
    rowIndex: number,
    columnIndex: number,
  ): { kind: ComposedKind; moduleId: string }[] => {
    const seen = new Set<ComposedKind>()
    const result: { kind: ComposedKind; moduleId: string }[] = []
    cellMembers(groupId, rowIndex, columnIndex).forEach((m) => {
      const kind = moduleComposedKind(m)
      if (!kind || seen.has(kind)) return
      seen.add(kind)
      result.push({ kind, moduleId: m.id })
    })
    return result
  }

  /**
   * 셀 안의 구성 요소 순서 변경 (좌측 '구성 요소' 리스트 드래그).
   * orderedModuleIds에 준 모듈들이 modules 배열에서 이미 차지하고 있던 자리들에 새 순서로 재배치한다
   * → 같은 셀의 다른 모듈(구성 요소 아닌 것)·다른 셀/그룹의 순서는 건드리지 않는다.
   */
  const reorderColumnElements = (
    groupId: string,
    rowIndex: number,
    columnIndex: number,
    orderedModuleIds: string[],
  ): void => {
    if (orderedModuleIds.length < 2) return
    const members = cellMembers(groupId, rowIndex, columnIndex).filter((m) =>
      orderedModuleIds.includes(m.id),
    )
    if (members.length !== orderedModuleIds.length) return
    const slots = members.map((m) => modules.value.indexOf(m)).sort((a, b) => a - b)
    const next = orderedModuleIds
      .map((id) => members.find((m) => m.id === id))
      .filter((m): m is ModuleInstance => !!m)
    if (next.length !== slots.length) return
    slots.forEach((slot, i) => {
      modules.value[slot] = next[i]
    })
    reorderModules()
    triggerRef(modules)
    isDirty.value = true
  }

  // 셀에 특정 구성 요소가 존재하는지
  const hasColumnElement = (
    groupId: string,
    rowIndex: number,
    columnIndex: number,
    kind: ComposedKind,
  ): boolean => cellMembers(groupId, rowIndex, columnIndex).some((m) => moduleComposedKind(m) === kind)

  // 구성 요소 토글: on=true면 기본값으로 생성해 셀에 추가(+선택), off면 그 종류 모듈을 셀에서 제거
  const setColumnElement = (
    groupId: string,
    rowIndex: number,
    columnIndex: number,
    kind: ComposedKind,
    on: boolean,
  ): void => {
    if (on) {
      if (hasColumnElement(groupId, rowIndex, columnIndex, kind)) return
      const spec = COMPOSED_SPECS[kind]
      const meta = availableModules.value.find((m) => m.id === spec.moduleId)
      if (!meta) return
      const properties: Record<string, unknown> = { ...getDefaultProperties(meta), ...spec.overrides }
      // 타이틀/텍스트(둘 다 ModuleDescText) 구분용 마커
      if (spec.moduleId === 'ModuleDescText') properties.__composedKind = kind
      const newModule: ModuleInstance = {
        id: generateUniqueId('module'),
        moduleId: meta.id,
        order: 0,
        groupId,
        rowIndex,
        columnIndex,
        properties,
        styles: meta.defaultStyles || {},
      }
      const lastIdx = modules.value.map((m) => m.groupId).lastIndexOf(groupId)
      if (lastIdx === -1) return
      modules.value.splice(lastIdx + 1, 0, newModule)
      reorderModules()
      // 속성 폼을 유지한 채 새 원소를 선택(구성 요소 + 새 모듈 속성 계속 노출). selectAddedModule은
      // forceRailPanel을 켜서 팔레트로 전환되므로 여기서는 selectModule을 쓴다.
      selectModule(newModule.id)
      isDirty.value = true
    } else {
      const target = cellMembers(groupId, rowIndex, columnIndex).find(
        (m) => moduleComposedKind(m) === kind,
      )
      if (!target) return
      // 제거 후에도 구성 요소가 유지되도록, 같은 셀의 다른 멤버를 선택(없으면 선택 해제).
      const wasSelected = selectedModuleId.value === target.id
      const rest = cellMembers(groupId, rowIndex, columnIndex).filter((m) => m.id !== target.id)
      removeModule(target.id)
      if (wasSelected && rest.length > 0) selectModule(rest[0].id)
    }
  }

  /** [행별 컬럼] 모듈을 같은 행 안에서 왼쪽/오른쪽 이웃 컬럼으로 이동 */
  const moveModuleColumn = (moduleId: string, direction: 'left' | 'right'): void => {
    const mod = modules.value.find((m) => m.id === moduleId)
    if (!mod || !mod.groupId) return
    const group = groups.value.find((g) => g.id === mod.groupId)
    if (!group) return
    ensureGroupRows(group)
    const rows = group.rows as number[]
    const r = Math.min(Math.max(mod.rowIndex ?? 0, 0), rows.length - 1)
    const cols = rows[r]
    if (cols <= 1) return
    const cur = mod.columnIndex ?? 0
    const next = Math.min(Math.max(cur + (direction === 'right' ? 1 : -1), 0), cols - 1)
    if (next === cur) return
    mod.columnIndex = next
    triggerRef(modules)
    selectedModuleId.value = moduleId
    isDirty.value = true
  }

  /**
   * 모듈 선택
   */
  const selectModule = (moduleId: string): void => {
    selectedModuleId.value = moduleId
    selectedGroupId.value = null
    // 사용자가 직접 선택한 것이므로 속성 패널로 전환한다.
    // (추가 직후 자동 선택된 모듈을 다시 클릭해도 확실히 전환되도록 id 변화와 무관하게 명시)
    useEditorStore().forceRailPanel = false
  }

  /**
   * 모듈 속성 업데이트
   */
  const updateModuleProperty = (propertyKey: string, value: unknown): void => {
    if (!selectedModule.value) return
    selectedModule.value.properties[propertyKey] = value
    // 🐛 해결책: 속성 변경 후 modules ref 트리거
    triggerRef(modules)
    isDirty.value = true
  }

  /**
   * 모듈 스타일 업데이트
   */
  const updateModuleStyle = (styleKey: string, value: unknown): void => {
    if (!selectedModule.value) return
    ;(selectedModule.value.styles as Record<string, unknown>)[styleKey] = value
    triggerRef(modules)
    isDirty.value = true
  }

  /**
   * 모듈 제거
   */
  const removeModule = (moduleId: string): void => {
    const index = modules.value.findIndex((m) => m.id === moduleId)
    if (index === -1) return

    const removedGroupId = modules.value[index].groupId
    modules.value.splice(index, 1)
    if (selectedModuleId.value === moduleId) {
      selectedModuleId.value = null
    }
    // 멤버가 0개가 된(빈) 그룹은 자동 해제 (1개짜리 그룹은 허용)
    if (removedGroupId) cleanupGroup(removedGroupId)
    reorderModules()
    isDirty.value = true
  }

  /**
   * 그룹에 멤버가 하나도 없으면(빈 그룹) 그룹 정의를 삭제한다.
   * (1개짜리 그룹도 그룹 스타일 적용을 위해 허용한다)
   */
  const cleanupGroup = (groupId: string): void => {
    const members = modules.value.filter((m) => m.groupId === groupId)
    if (members.length < 1) {
      members.forEach((m) => {
        delete m.groupId
      })
      const gi = groups.value.findIndex((g) => g.id === groupId)
      if (gi !== -1) groups.value.splice(gi, 1)
      if (selectedGroupId.value === groupId) selectedGroupId.value = null
    }
  }

  /**
   * 모듈 순서 재정렬
   */
  const reorderModules = (): void => {
    modules.value.forEach((module, idx) => {
      module.order = idx
    })
  }

  /**
   * 모듈 위로 이동
   */
  const moveModuleUp = (moduleId: string): void => {
    const index = modules.value.findIndex((m) => m.id === moduleId)
    if (index <= 0) return
    // 그룹 연속성 보호: 위 이웃과 그룹 소속이 같을 때만 교환
    // (그룹 경계에서는 동작하지 않음 — 그룹 통째 이동은 드래그/그룹 이동 사용)
    if ((modules.value[index].groupId ?? null) !== (modules.value[index - 1].groupId ?? null)) {
      return
    }
    ;[modules.value[index], modules.value[index - 1]] = [
      modules.value[index - 1],
      modules.value[index],
    ]
    reorderModules()
    isDirty.value = true
  }

  /**
   * 모듈 아래로 이동
   */
  const moveModuleDown = (moduleId: string): void => {
    const index = modules.value.findIndex((m) => m.id === moduleId)
    if (index < 0 || index >= modules.value.length - 1) return
    // 그룹 연속성 보호: 아래 이웃과 그룹 소속이 같을 때만 교환
    if ((modules.value[index].groupId ?? null) !== (modules.value[index + 1].groupId ?? null)) {
      return
    }
    ;[modules.value[index], modules.value[index + 1]] = [
      modules.value[index + 1],
      modules.value[index],
    ]
    reorderModules()
    isDirty.value = true
  }

  /**
   * 모듈 복제
   */
  const duplicateModule = (moduleId: string): void => {
    const originalModule = modules.value.find((m) => m.id === moduleId)
    if (!originalModule) return

    const duplicatedModule: ModuleInstance = {
      ...originalModule,
      id: generateUniqueId('module'),
      order: originalModule.order + 1,
      properties: JSON.parse(JSON.stringify(originalModule.properties)),
      styles: JSON.parse(JSON.stringify(originalModule.styles)),
    }

    const insertIndex = modules.value.findIndex((m) => m.id === moduleId) + 1
    modules.value.splice(insertIndex, 0, duplicatedModule)
    reorderModules()

    selectedModuleId.value = duplicatedModule.id
    isDirty.value = true
  }

  /**
   * 전체 삭제
   */
  const clearAll = (): void => {
    modules.value = []
    groups.value = []
    selectedModuleId.value = null
    selectedGroupId.value = null
    isDirty.value = false
  }

  // ============= Group Management =============
  /**
   * 선택된 모듈들을 하나의 그룹으로 묶는다.
   * - 1개 이상이면 가능하며(단일 모듈 그룹 허용), 묶인 결과는 항상 '연속'되도록 순서를 재배치한다.
   * - 이미 다른 그룹에 속한 모듈이 하나라도 포함되면 그룹을 만들지 않고 null을 반환한다.
   *   (기존 그룹을 먼저 해제한 뒤 다시 묶어야 한다)
   * @returns 생성된 그룹 id (실패 시 null)
   */
  const createGroup = (moduleIds: string[]): string | null => {
    const ids = Array.from(new Set(moduleIds))
    if (ids.length < 1) return null

    const targets = ids
      .map((id) => modules.value.find((m) => m.id === id))
      .filter((m): m is ModuleInstance => !!m)
    if (targets.length < 1) return null

    // 이미 그룹에 속한 모듈이 포함되면 묶지 않고 그대로 반환
    if (targets.some((m) => m.groupId)) return null

    const newGroupId = generateUniqueId('group')

    // 묶을 모듈들을 현재 order 순으로 정렬
    const sortedTargets = [...targets].sort((a, b) => a.order - b.order)
    // 새 위치: 첫 멤버가 있던 자리에 모두 연속 배치
    const firstIndex = modules.value
      .map((m) => m.id)
      .indexOf(sortedTargets[0].id)

    const targetIdSet = new Set(sortedTargets.map((m) => m.id))
    const remaining = modules.value.filter((m) => !targetIdSet.has(m.id))

    // firstIndex 기준으로 remaining 위치를 계산해 그 자리에 그룹 멤버 삽입
    // (firstIndex 앞에 있던 비대상 모듈 수 = 삽입 위치)
    const insertAt = modules.value
      .slice(0, firstIndex)
      .filter((m) => !targetIdSet.has(m.id)).length

    // 멤버가 이미 rowIndex/columnIndex를 갖고 있으면(조립형) 그 배치를 존중하고,
    // 없으면 1행·1컬럼 세로 스택으로 둔다.
    sortedTargets.forEach((m) => {
      m.groupId = newGroupId
      if (m.rowIndex == null) m.rowIndex = 0
      if (m.columnIndex == null) m.columnIndex = 0
      delete m.fullWidth
    })

    const next = [...remaining]
    next.splice(insertAt, 0, ...sortedTargets)
    modules.value.splice(0, modules.value.length, ...next)

    groups.value.push({
      id: newGroupId,
      styles: { ...DEFAULT_GROUP_STYLES },
      rows: deriveRowsFromMembers(sortedTargets),
    })

    reorderModules()
    selectedGroupId.value = newGroupId
    selectedModuleId.value = null
    isDirty.value = true
    return newGroupId
  }

  /**
   * [행별 컬럼] 선택 모듈들을 하나의 그룹으로 병합한다. (이미 그룹인 것도 허용)
   * - 각 기존 그룹의 (행,컬럼) 구조는 보존되어 새 그룹에서 연속된 행 블록이 된다.
   * - 그룹에 안 속했던 단독 모듈은 각각 1컬럼 행이 된다.
   * → "1컬럼짜리 + 2컬럼 그룹"을 합치면 1컬럼 행 + 2컬럼 행을 가진 한 그룹이 된다.
   * @returns 새 그룹 id (실패 시 null)
   */
  const mergeModulesIntoGroup = (moduleIds: string[]): string | null => {
    const targets = moduleIds
      .map((id) => modules.value.find((m) => m.id === id))
      .filter((m): m is ModuleInstance => !!m)
    if (targets.length < 1) return null

    // 관련된 기존 그룹을 행 모델로 승격
    const involvedGroupIds = new Set(
      targets.map((m) => m.groupId).filter((g): g is string => !!g),
    )
    involvedGroupIds.forEach((gid) => {
      const g = groups.value.find((x) => x.id === gid)
      if (g) ensureGroupRows(g)
    })

    const sortedTargets = [...targets].sort((a, b) => a.order - b.order)
    const newGroupId = generateUniqueId('group')

    // 새 행 배정: (기존 그룹 + 기존 행) 단위로 묶고, 단독 모듈은 각각 새 행
    const rowKeyToNewIndex = new Map<string, number>()
    const newRows: number[] = []
    const plan = sortedTargets.map((m) => {
      const key = m.groupId ? `${m.groupId}:${m.rowIndex ?? 0}` : `solo:${m.id}`
      let newRow = rowKeyToNewIndex.get(key)
      if (newRow == null) {
        newRow = newRows.length
        rowKeyToNewIndex.set(key, newRow)
        newRows.push(1)
      }
      const col = m.groupId ? m.columnIndex ?? 0 : 0
      newRows[newRow] = Math.max(newRows[newRow], clampColumns(col + 1))
      return { m, newRow, col }
    })

    // 위치 계산 (첫 멤버 자리에 연속 배치)
    const firstIndex = modules.value.map((m) => m.id).indexOf(sortedTargets[0].id)
    const targetIdSet = new Set(sortedTargets.map((m) => m.id))
    const remaining = modules.value.filter((m) => !targetIdSet.has(m.id))
    const insertAt = modules.value
      .slice(0, firstIndex)
      .filter((m) => !targetIdSet.has(m.id)).length

    // 배치 적용
    plan.forEach(({ m, newRow, col }) => {
      m.groupId = newGroupId
      m.rowIndex = newRow
      m.columnIndex = col
      delete m.fullWidth
    })

    const next = [...remaining]
    next.splice(insertAt, 0, ...sortedTargets)
    modules.value.splice(0, modules.value.length, ...next)

    groups.value.push({ id: newGroupId, styles: { ...DEFAULT_GROUP_STYLES }, rows: newRows })

    // 비게 된 기존 그룹 정의 제거, 멤버가 남은 그룹은 rows 재유도
    involvedGroupIds.forEach((gid) => {
      const rest = modules.value.filter((m) => m.groupId === gid)
      if (rest.length === 0) {
        const gi = groups.value.findIndex((g) => g.id === gid)
        if (gi !== -1) groups.value.splice(gi, 1)
        if (selectedGroupId.value === gid) selectedGroupId.value = null
      } else {
        const g = groups.value.find((x) => x.id === gid)
        if (g) g.rows = deriveRowsFromMembers(rest.sort((a, b) => a.order - b.order))
      }
    })

    reorderModules()
    selectedGroupId.value = newGroupId
    selectedModuleId.value = null
    triggerRef(groups)
    triggerRef(modules)
    isDirty.value = true
    return newGroupId
  }

  /**
   * 그룹 통째 복제 — 그룹의 모든 멤버 모듈 + 그룹 스타일을 새 ID로 복제해
   * 원본 그룹 바로 아래에 연속 배치한다. (그룹 연속성 유지)
   * @returns 생성된 새 그룹 id (실패 시 null)
   */
  const duplicateGroup = (groupId: string): string | null => {
    const group = groups.value.find((g) => g.id === groupId)
    if (!group) return null

    // 원본 그룹 멤버를 현재 order 순으로
    const members = modules.value
      .filter((m) => m.groupId === groupId)
      .sort((a, b) => a.order - b.order)
    if (members.length === 0) return null

    const newGroupId = generateUniqueId('group')

    // 멤버 복제 (새 모듈 ID + 새 groupId, 속성·스타일 깊은 복사)
    const clones: ModuleInstance[] = members.map((m) => ({
      ...m,
      id: generateUniqueId('module'),
      groupId: newGroupId,
      properties: JSON.parse(JSON.stringify(m.properties)),
      styles: JSON.parse(JSON.stringify(m.styles)),
    }))

    // 원본 그룹의 마지막 멤버 바로 뒤에 연속 삽입
    const lastMemberId = members[members.length - 1].id
    const insertIndex = modules.value.findIndex((m) => m.id === lastMemberId) + 1
    modules.value.splice(insertIndex, 0, ...clones)

    // 그룹 정의 복제 (스타일 깊은 복사, 이름도 함께 승계)
    // rows(행별 컬럼 수)를 빠뜨리면 멤버는 rowIndex/columnIndex를 그대로 물려받는데 그룹엔 행 정보가
    // 없어 다단 레이아웃이 깨진다 (createGroup/mergeModulesIntoGroup은 rows를 명시함).
    groups.value.push({
      id: newGroupId,
      name: group.name,
      rows: group.rows ? [...group.rows] : undefined,
      styles: JSON.parse(JSON.stringify(group.styles)),
    })

    reorderModules()
    selectedGroupId.value = newGroupId
    selectedModuleId.value = null
    isDirty.value = true
    return newGroupId
  }

  /**
   * 그룹 해제 — 멤버들의 groupId 제거, 그룹 정의 삭제 (모듈 자체는 유지)
   */
  const ungroup = (groupId: string): void => {
    modules.value.forEach((m) => {
      if (m.groupId === groupId) delete m.groupId
    })
    const gi = groups.value.findIndex((g) => g.id === groupId)
    if (gi !== -1) groups.value.splice(gi, 1)
    if (selectedGroupId.value === groupId) selectedGroupId.value = null
    isDirty.value = true
  }

  /**
   * 그룹 전체 삭제 — 그룹의 모든 멤버 모듈과 그룹 정의를 함께 제거한다.
   * (그룹 해제(ungroup)는 모듈을 유지하지만, 이 함수는 모듈까지 삭제한다)
   */
  const deleteGroup = (groupId: string): void => {
    const hadMembers = modules.value.some((m) => m.groupId === groupId)
    // 멤버 모듈 제거
    modules.value = modules.value.filter((m) => m.groupId !== groupId)
    // 그룹 정의 제거
    const gi = groups.value.findIndex((g) => g.id === groupId)
    if (gi !== -1) groups.value.splice(gi, 1)
    // 선택 상태 정리
    if (selectedGroupId.value === groupId) selectedGroupId.value = null
    if (
      selectedModuleId.value &&
      !modules.value.some((m) => m.id === selectedModuleId.value)
    ) {
      selectedModuleId.value = null
    }
    if (hadMembers || gi !== -1) {
      reorderModules()
      isDirty.value = true
    }
  }

  /**
   * 그룹 선택 (속성 패널에서 그룹 스타일 편집)
   */
  const selectGroup = (groupId: string): void => {
    selectedGroupId.value = groupId
    selectedModuleId.value = null
  }

  /** 모듈/그룹 선택 해제 — 좌측 레일 메뉴로 이동할 때 캔버스 선택 상태를 비운다 */
  const clearSelection = (): void => {
    selectedModuleId.value = null
    selectedGroupId.value = null
  }

  /**
   * 그룹 스타일 업데이트
   */
  const updateGroupStyle = (
    groupId: string,
    styleKey: keyof ModuleGroupStyles,
    value: ModuleGroupStyles[keyof ModuleGroupStyles],
  ): void => {
    const group = groups.value.find((g) => g.id === groupId)
    if (!group) return
    ;(group.styles as Record<string, unknown>)[styleKey] = value
    triggerRef(groups)
    isDirty.value = true
  }

  // 조립형(v2) 템플릿에서 만든 그룹에 표시용 이름을 붙인다(예: "이미지형 헤더").
  // 좌측 "그룹 구성" 패널이 이 이름을 타이틀로 보여준다 — 없으면 일반 라벨로 대체.
  const setGroupName = (groupId: string, name: string): void => {
    const group = groups.value.find((g) => g.id === groupId)
    if (!group) return
    group.name = name
    triggerRef(groups)
  }

  /**
   * 표시 항목(displayItems) 순서를 새 배열로 적용 — 평평한 modules 배열로 펼쳐 재구성.
   * 그룹 항목은 내부 모듈을 통째로 유지하므로 그룹 연속성이 보존된다.
   * (캔버스/목차 상위 레벨 드래그에서 호출)
   */
  const setDisplayOrder = (items: DisplayItem[]): void => {
    const flat: ModuleInstance[] = []
    for (const item of items) {
      if (item.type === 'group') {
        flat.push(...item.modules)
      } else {
        flat.push(item.module)
      }
    }
    modules.value.splice(0, modules.value.length, ...flat)
    reorderModules()
    isDirty.value = true
  }

  /**
   * 그룹을 표시 단위로 위/아래 한 칸 이동 (그룹 통째 이동)
   */
  const moveGroup = (groupId: string, direction: 'up' | 'down'): void => {
    const items = displayItems.value
    const idx = items.findIndex((it) => it.type === 'group' && it.id === groupId)
    if (idx === -1) return
    const swapWith = direction === 'up' ? idx - 1 : idx + 1
    if (swapWith < 0 || swapWith >= items.length) return
    const next = [...items]
    ;[next[idx], next[swapWith]] = [next[swapWith], next[idx]]
    setDisplayOrder(next)
  }

  /**
   * [그룹 내부] 드래그로 재배치된 '행' 순서를 반영한다.
   * orderedRows = 캔버스에서 새로 정렬된 GroupRowLayout 배열(각 행의 cells에 멤버 포함).
   * - 각 멤버의 rowIndex/columnIndex를 새 행/열 위치로 갱신
   * - group.rows(행별 컬럼 수)를 새 순서로 재구성
   * - modules 배열에서 그 그룹의 연속 멤버 구간을 새 순서로 교체
   */
  const reorderGroupRows = (
    groupId: string,
    orderedRows: GroupRowLayout<ModuleInstance>[],
  ): void => {
    const group = groups.value.find((g) => g.id === groupId)
    if (!group) return
    const newRowCols: number[] = []
    const newOrderIds: string[] = []
    orderedRows.forEach((row, r) => {
      newRowCols.push(row.columns)
      row.cells.forEach((cellMembers, c) => {
        cellMembers.forEach((m) => {
          const mod = modules.value.find((x) => x.id === m.id)
          if (mod) {
            mod.rowIndex = r
            mod.columnIndex = c
          }
          newOrderIds.push(m.id)
        })
      })
    })
    if (newOrderIds.length === 0) return
    group.rows = newRowCols
    // 그룹 멤버(연속 구간)를 새 순서로 교체
    const memberSet = new Set(newOrderIds)
    const start = modules.value.findIndex((m) => memberSet.has(m.id))
    if (start < 0) return
    const orderedMembers = newOrderIds
      .map((id) => modules.value.find((m) => m.id === id))
      .filter((m): m is ModuleInstance => !!m)
    modules.value.splice(start, orderedMembers.length, ...orderedMembers)
    reorderModules()
    triggerRef(modules)
    triggerRef(groups)
    isDirty.value = true
  }

  /**
   * 저장됨으로 표시 (내보내기 후 호출)
   */
  const markAsSaved = (): void => {
    isDirty.value = false
  }

  // ============= Newsletter Templates =============
  /**
   * 사용 가능한 뉴스레터 템플릿 카탈로그 로드
   */
  const loadAvailableTemplates = async (): Promise<NewsletterTemplate[]> => {
    try {
      const basePath = import.meta.env.BASE_URL || '/'
      const configPath = normalizePath(`${basePath}templates/templates-config.json`)

      const response = await fetch(configPath)
      if (!response.ok) {
        throw new Error(`Failed to load templates: ${response.status}`)
      }

      const data = await response.json()
      if (!data || !Array.isArray(data.templates)) {
        throw new Error('Invalid templates configuration format')
      }

      const validated = (data.templates as NewsletterTemplate[]).filter(
        (t) => t && typeof t.id === 'string' && typeof t.name === 'string' && Array.isArray(t.modules),
      )

      availableTemplates.value = validated
      return validated
    } catch (error) {
      console.error('[loadAvailableTemplates] Failed:', error)
      availableTemplates.value = []
      return []
    }
  }

  /**
   * 템플릿을 현재 작업 영역에 로드
   * 모듈 ID는 충돌 방지를 위해 재생성됨
   */
  const loadTemplate = async (templateId: string): Promise<boolean> => {
    const template = availableTemplates.value.find((t) => t.id === templateId)
    if (!template) {
      console.error(`[loadTemplate] Template not found: ${templateId}`)
      return false
    }

    if (availableModules.value.length === 0) {
      await loadAvailableModules()
    }

    const editorStore = useEditorStore()

    clearAll()

    if (template.wrapSettings) {
      editorStore.updateWrapSettings(template.wrapSettings)
    }

    // 배열 순서를 그대로 적용 (JSON 작성 시 직관적으로 추가/삭제 가능)
    for (const moduleData of template.modules) {
      const moduleMetadata = availableModules.value.find((m) => m.id === moduleData.moduleId)
      if (!moduleMetadata) {
        console.warn(`[loadTemplate] Unknown moduleId skipped: ${moduleData.moduleId}`)
        continue
      }

      addModule(moduleMetadata)
      const added = modules.value[modules.value.length - 1]

      // 구버전 템플릿 속성을 현재 스키마로 변환 후 적용
      const migratedProps = migrateModuleProperties(moduleData.moduleId, moduleData.properties)
      Object.entries(migratedProps).forEach(([key, value]) => {
        added.properties[key] = value
      })
      if (moduleData.styles) {
        Object.entries(moduleData.styles).forEach(([key, value]) => {
          ;(added.styles as Record<string, unknown>)[key] = value
        })
      }
      // 그룹 소속 복원 (그룹 정의는 아래에서 일괄 복원)
      if (moduleData.groupId) {
        added.groupId = moduleData.groupId
      }
      // 행/컬럼 인덱스 복원 (행별 독립 컬럼 그룹)
      if (moduleData.rowIndex != null) {
        added.rowIndex = moduleData.rowIndex
      }
      if (moduleData.columnIndex != null) {
        added.columnIndex = moduleData.columnIndex
      }
      if (moduleData.fullWidth) {
        added.fullWidth = true // 레거시 데이터 — 렌더 시 rows로 유도됨
      }
    }

    // 그룹 정의 복원 후 연속성 정리
    if (template.groups && template.groups.length > 0) {
      groups.value = JSON.parse(JSON.stringify(template.groups))
      normalizeGroupContiguity()
    }

    if (modules.value.length > 0) {
      selectedModuleId.value = modules.value[0].id
    }
    isDirty.value = false
    return true
  }

  /**
   * 그룹 멤버가 항상 '연속'이 되도록 modules 순서를 안정적으로 재배치한다.
   * (가져오기/템플릿 로드처럼 외부에서 순서가 들어올 때 방어적으로 호출)
   * 또한 정의가 없는 groupId나 멤버 2개 미만 그룹은 정리한다.
   */
  const normalizeGroupContiguity = (): void => {
    const sorted = [...modules.value].sort((a, b) => a.order - b.order)
    const validGroupIds = new Set(groups.value.map((g) => g.id))

    // 정의 없는 groupId 제거
    sorted.forEach((m) => {
      if (m.groupId && !validGroupIds.has(m.groupId)) delete m.groupId
    })

    const emitted = new Set<string>()
    const result: ModuleInstance[] = []
    for (const m of sorted) {
      const gid = m.groupId
      if (gid && !emitted.has(gid)) {
        // 이 그룹의 모든 멤버를 현재 상대 순서대로 연속 배치
        result.push(...sorted.filter((x) => x.groupId === gid))
        emitted.add(gid)
      } else if (!gid) {
        result.push(m)
      }
      // 이미 emit된 그룹 멤버는 건너뜀
    }
    modules.value.splice(0, modules.value.length, ...result)
    reorderModules()

    // 멤버 2개 미만 그룹 정리
    ;[...groups.value].forEach((g) => cleanupGroup(g.id))
  }

  /**
   * 현재 작업 상태를 템플릿 JSON 문자열로 직렬화
   * 외부에서 이름/설명을 받아 그대로 사용
   */
  const exportCurrentAsTemplate = (name: string, description: string = ''): string => {
    const editorStore = useEditorStore()
    const template: NewsletterTemplate = {
      id: `template-${Date.now()}`,
      name,
      description,
      wrapSettings: { ...editorStore.wrapSettings },
      modules: modules.value.map((m) => ({
        moduleId: m.moduleId,
        order: m.order,
        properties: JSON.parse(JSON.stringify(m.properties)),
        styles: JSON.parse(JSON.stringify(m.styles)),
        ...(m.groupId ? { groupId: m.groupId } : {}),
        ...(m.rowIndex != null ? { rowIndex: m.rowIndex } : {}),
        ...(m.columnIndex != null ? { columnIndex: m.columnIndex } : {}),
      })),
      groups: JSON.parse(JSON.stringify(groups.value)),
    }
    return JSON.stringify(template, null, 2)
  }

  // ============= Table Row Management =============
  const addTableRow = (moduleId: string, header: string = '', data: string = ''): void => {
    const moduleIndex = modules.value.findIndex((m) => m.id === moduleId)
    if (moduleIndex === -1) {
      console.error(`[addTableRow] Module not found: ${moduleId}`)
      return
    }

    const module = modules.value[moduleIndex]

    const newRow: TableRow = {
      id: generateUniqueId('row'),
      header,
      data,
    }

    // tableRows 초기화 및 추가
    const currentRows = (module.properties.tableRows as TableRow[]) || []

    // 🐛 해결책: modules.value를 직접 변경하고 triggerRef로 강제 업데이트
    module.properties.tableRows = [...currentRows, newRow]

    // modules ref를 강제로 트리거하여 Vue에게 변경을 알림
    triggerRef(modules)
  }

  const updateTableRow = (
    moduleId: string,
    rowId: string,
    field: 'header' | 'data',
    value: string,
  ): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module || !module.properties.tableRows) return

    const row = (module.properties.tableRows as TableRow[]).find((r: TableRow) => r.id === rowId)
    if (row) {
      row[field] = value
      triggerRef(modules)
      isDirty.value = true
    }
  }

  const removeTableRow = (moduleId: string, rowId: string): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module || !module.properties.tableRows) return

    const index = (module.properties.tableRows as TableRow[]).findIndex(
      (r: TableRow) => r.id === rowId,
    )
    if (index !== -1) {
      ;(module.properties.tableRows as TableRow[]).splice(index, 1)
      triggerRef(modules)
      isDirty.value = true
    }
  }

  // ============= Custom Table Cell Management =============
  /**
   * 테이블 셀 초기화 (기본 2x2 테이블)
   */
  const initializeTableCells = (moduleId: string): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    // 정렬은 셀별로 지정하지 않고 열 공통값(tableColAligns)을 기본으로 사용한다.
    // 셀별 align은 사용자가 '가' 편집기에서 직접 지정했을 때만 채워지며, 그때 더 우선한다.
    const defaultCells: TableCell[][] = [
      [
        { id: generateUniqueId('cell'), type: 'th', content: '항목', colspan: 1, rowspan: 1 },
        { id: generateUniqueId('cell'), type: 'td', content: '내용', colspan: 1, rowspan: 1 },
      ],
      [
        { id: generateUniqueId('cell'), type: 'th', content: '항목', colspan: 1, rowspan: 1 },
        { id: generateUniqueId('cell'), type: 'td', content: '내용', colspan: 1, rowspan: 1 },
      ],
    ]

    module.properties.tableCells = defaultCells
    // 열 공통 정렬: 1열 가운데, 2열 왼쪽
    module.properties.tableColAligns = ['center', 'left']
    triggerRef(modules)
  }

  /**
   * 각 셀 위치(r,c)를 실제로 소유(병합의 앵커)하는 셀 정보를 매핑한다.
   * 병합 앵커는 colspan/rowspan 범위의 모든 칸을 소유하며, 삽입 위치가 병합 영역
   * '내부'인지(=양옆/위아래 칸의 소유주가 같은지) 판정하는 데 사용한다.
   */
  const buildCellOwners = (
    cells: TableCell[][]
  ): { cell: TableCell; row: number; col: number }[][] => {
    const rowCount = cells.length
    const colCount = cells[0]?.length ?? 0
    const owners: ({ cell: TableCell; row: number; col: number } | null)[][] = Array.from(
      { length: rowCount },
      () => new Array(colCount).fill(null)
    )
    for (let r = 0; r < rowCount; r++) {
      for (let c = 0; c < colCount; c++) {
        const cell = cells[r][c]
        if (cell.hidden) continue
        const info = { cell, row: r, col: c }
        const rs = cell.rowspan || 1
        const cs = cell.colspan || 1
        for (let dr = 0; dr < rs && r + dr < rowCount; dr++) {
          for (let dc = 0; dc < cs && c + dc < colCount; dc++) {
            owners[r + dr][c + dc] = info
          }
        }
      }
    }
    return owners as { cell: TableCell; row: number; col: number }[][]
  }

  /**
   * 테이블 행 삽입 (커스텀 테이블)
   * @param atIndex 새 행이 들어갈 위치(0 = 맨 위, cells.length = 맨 아래).
   *   병합(rowspan) 영역을 가로지르는 위치면 해당 병합을 한 칸 늘려 유지한다.
   */
  const insertTableCellRow = (moduleId: string, atIndex: number): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []

    // 첫 행이 없으면 초기화
    if (cells.length === 0) {
      initializeTableCells(moduleId)
      return
    }

    const rowCount = cells.length
    const colCount = cells[0].length
    const idx = Math.max(0, Math.min(atIndex, rowCount))
    const owners = buildCellOwners(cells)

    const newRow: TableCell[] = []
    for (let c = 0; c < colCount; c++) {
      // 삽입 경계(idx-1 행과 idx 행 사이)가 세로 병합 내부인지 판정
      const insideMerge =
        idx > 0 && idx < rowCount && !!owners[idx - 1][c] && owners[idx - 1][c] === owners[idx][c]
      if (insideMerge) {
        const anchor = owners[idx - 1][c]
        // 병합의 왼쪽 위(앵커) 칸에서 한 번만 rowspan을 늘린다
        if (anchor.col === c) anchor.cell.rowspan = (anchor.cell.rowspan || 1) + 1
        newRow.push({
          id: generateUniqueId('cell'),
          type: anchor.cell.type,
          content: '',
          colspan: 1,
          rowspan: 1,
          hidden: true,
        })
      } else {
        newRow.push({
          id: generateUniqueId('cell'),
          type: 'td',
          content: '',
          colspan: 1,
          rowspan: 1,
        })
      }
    }

    cells.splice(idx, 0, newRow)
    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 테이블 열 삽입 (커스텀 테이블)
   * @param atIndex 새 열이 들어갈 위치(0 = 맨 왼쪽, 열 개수 = 맨 오른쪽).
   *   병합(colspan) 영역을 가로지르는 위치면 해당 병합을 한 칸 늘려 유지한다.
   */
  const insertTableCellColumn = (moduleId: string, atIndex: number): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []

    if (cells.length === 0) {
      initializeTableCells(moduleId)
      return
    }

    const colCount = cells[0].length
    const idx = Math.max(0, Math.min(atIndex, colCount))
    const owners = buildCellOwners(cells)

    cells.forEach((row, r) => {
      // 삽입 경계(idx-1 열과 idx 열 사이)가 가로 병합 내부인지 판정
      const insideMerge =
        idx > 0 && idx < colCount && !!owners[r][idx - 1] && owners[r][idx - 1] === owners[r][idx]
      if (insideMerge) {
        const anchor = owners[r][idx - 1]
        // 병합의 왼쪽 위(앵커) 칸에서 한 번만 colspan을 늘린다
        if (anchor.row === r) anchor.cell.colspan = (anchor.cell.colspan || 1) + 1
        row.splice(idx, 0, {
          id: generateUniqueId('cell'),
          type: anchor.cell.type,
          content: '',
          colspan: 1,
          rowspan: 1,
          hidden: true,
        })
      } else {
        row.splice(idx, 0, {
          id: generateUniqueId('cell'),
          type: r === 0 ? 'th' : 'td',
          content: '',
          colspan: 1,
          rowspan: 1,
        })
      }
    })

    // 열 너비 배열도 동기화 (새 열은 기본 너비)
    const colWidths = (module.properties.tableColWidths as string[] | undefined) || []
    {
      const next = [...colWidths]
      while (next.length < colCount) next.push('')
      next.splice(idx, 0, '')
      module.properties.tableColWidths = next
    }

    // 열 공통 정렬 배열도 동기화 (첫 열은 가운데, 나머지는 왼쪽 기본)
    const colAligns = (module.properties.tableColAligns as string[] | undefined) || []
    {
      const next = [...colAligns]
      while (next.length < colCount) next.push('left')
      next.splice(idx, 0, idx === 0 ? 'center' : 'left')
      module.properties.tableColAligns = next
    }

    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 테이블 행 추가 (커스텀 테이블) — 맨 아래에 삽입
   */
  const addTableCellRow = (moduleId: string): void => {
    const cells = (modules.value.find((m) => m.id === moduleId)?.properties.tableCells ??
      []) as TableCell[][]
    insertTableCellRow(moduleId, cells.length)
  }

  /**
   * 테이블 열 추가 (커스텀 테이블) — 맨 오른쪽에 삽입
   */
  const addTableCellColumn = (moduleId: string): void => {
    const cells = (modules.value.find((m) => m.id === moduleId)?.properties.tableCells ??
      []) as TableCell[][]
    insertTableCellColumn(moduleId, cells[0]?.length ?? 0)
  }

  /**
   * 테이블 행 삭제 (커스텀 테이블)
   */
  const removeTableCellRow = (moduleId: string, rowIndex: number): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    if (rowIndex < 0 || rowIndex >= cells.length || cells.length <= 1) return

    cells.splice(rowIndex, 1)
    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 테이블 열 삭제 (커스텀 테이블)
   */
  const removeTableCellColumn = (moduleId: string, colIndex: number): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    if (cells.length === 0 || colIndex < 0 || colIndex >= cells[0].length || cells[0].length <= 1) return

    cells.forEach((row) => {
      row.splice(colIndex, 1)
    })

    // 열 너비 배열도 동기화
    const colWidths = (module.properties.tableColWidths as string[] | undefined) || []
    if (colWidths.length > 0) {
      const next = [...colWidths]
      next.splice(colIndex, 1)
      module.properties.tableColWidths = next
    }

    // 열 공통 정렬 배열도 동기화
    const colAligns = (module.properties.tableColAligns as string[] | undefined) || []
    if (colAligns.length > 0) {
      const next = [...colAligns]
      next.splice(colIndex, 1)
      module.properties.tableColAligns = next
    }

    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 테이블 열 너비 업데이트 (커스텀 테이블)
   */
  const updateTableColWidth = (moduleId: string, colIndex: number, width: string): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    const colCount = cells[0]?.length || 0
    if (colIndex < 0 || colIndex >= colCount) return

    const current = (module.properties.tableColWidths as string[] | undefined) || []
    const next = Array.from({ length: colCount }, (_, i) => current[i] ?? '')
    next[colIndex] = (width || '').trim()

    module.properties.tableColWidths = next
    triggerRef(modules)
  }

  /**
   * 테이블 열 공통 정렬 업데이트 (커스텀 테이블)
   * 셀별 align이 지정되지 않은 셀에 적용되는 열 단위 기본 정렬.
   */
  const updateTableColAlign = (
    moduleId: string,
    colIndex: number,
    align: 'left' | 'center' | 'right',
  ): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    const colCount = cells[0]?.length || 0
    if (colIndex < 0 || colIndex >= colCount) return

    const current = (module.properties.tableColAligns as string[] | undefined) || []
    const next = Array.from({ length: colCount }, (_, i) => current[i] || (i === 0 ? 'center' : 'left'))
    next[colIndex] = align

    module.properties.tableColAligns = next
    triggerRef(modules)
  }

  /**
   * 테이블 셀 업데이트 (colspan/rowspan 변경 시 hidden 셀 처리 포함)
   */
  const updateTableCell = (
    moduleId: string,
    rowIndex: number,
    colIndex: number,
    updates: Partial<TableCell>
  ): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    if (rowIndex < 0 || rowIndex >= cells.length) return
    if (colIndex < 0 || colIndex >= cells[rowIndex].length) return

    const cell = cells[rowIndex][colIndex]
    const prevColspan = cell.colspan || 1
    const prevRowspan = cell.rowspan || 1

    // colspan 또는 rowspan이 변경되는 경우 hidden 셀 처리
    if (updates.colspan !== undefined || updates.rowspan !== undefined) {
      const newColspan = updates.colspan ?? prevColspan
      const newRowspan = updates.rowspan ?? prevRowspan

      // 기존 병합 해제 (이전에 hidden이었던 셀들 복원)
      for (let r = rowIndex; r < rowIndex + prevRowspan && r < cells.length; r++) {
        for (let c = colIndex; c < colIndex + prevColspan && c < cells[r].length; c++) {
          if (r !== rowIndex || c !== colIndex) {
            cells[r][c].hidden = false
          }
        }
      }

      // 새로운 병합 적용
      for (let r = rowIndex; r < rowIndex + newRowspan && r < cells.length; r++) {
        for (let c = colIndex; c < colIndex + newColspan && c < cells[r].length; c++) {
          if (r !== rowIndex || c !== colIndex) {
            cells[r][c].hidden = true
          }
        }
      }
    }

    Object.assign(cell, updates)

    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 셀 병합 (colspan/rowspan 설정)
   */
  const mergeCells = (
    moduleId: string,
    startRow: number,
    startCol: number,
    rowSpan: number,
    colSpan: number
  ): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    if (startRow < 0 || startRow >= cells.length) return
    if (startCol < 0 || startCol >= cells[startRow].length) return

    // 시작 셀에 colspan/rowspan 설정
    cells[startRow][startCol].colspan = colSpan
    cells[startRow][startCol].rowspan = rowSpan

    // 병합되는 나머지 셀들을 hidden으로 표시
    for (let r = startRow; r < startRow + rowSpan && r < cells.length; r++) {
      for (let c = startCol; c < startCol + colSpan && c < cells[r].length; c++) {
        if (r !== startRow || c !== startCol) {
          cells[r][c].hidden = true
        }
      }
    }

    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 셀 병합 해제
   */
  const unmergeCell = (moduleId: string, rowIndex: number, colIndex: number): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    if (rowIndex < 0 || rowIndex >= cells.length) return
    if (colIndex < 0 || colIndex >= cells[rowIndex].length) return

    const cell = cells[rowIndex][colIndex]
    const prevColspan = cell.colspan
    const prevRowspan = cell.rowspan

    // 병합 해제
    cell.colspan = 1
    cell.rowspan = 1

    // 병합되었던 셀들의 hidden 해제
    for (let r = rowIndex; r < rowIndex + prevRowspan && r < cells.length; r++) {
      for (let c = colIndex; c < colIndex + prevColspan && c < cells[r].length; c++) {
        cells[r][c].hidden = false
      }
    }

    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 셀 타입 토글 (th <-> td)
   * 타입 변경 시 기본 정렬도 함께 변경 (TH: center, TD: left)
   */
  const toggleCellType = (moduleId: string, rowIndex: number, colIndex: number): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    const cells = (module.properties.tableCells as TableCell[][]) || []
    if (rowIndex < 0 || rowIndex >= cells.length) return
    if (colIndex < 0 || colIndex >= cells[rowIndex].length) return

    const cell = cells[rowIndex][colIndex]
    const newType = cell.type === 'th' ? 'td' : 'th'
    cell.type = newType
    // 타입 변경 시 기본 정렬 적용 (TH: center, TD: left)
    cell.align = newType === 'th' ? 'center' : 'left'

    module.properties.tableCells = [...cells]
    triggerRef(modules)
  }

  /**
   * 테이블 프리셋 적용
   */
  const applyTablePreset = (
    moduleId: string,
    presetId: string,
    rows: number,
    cols: number,
    structure: ('th' | 'td')[][],
    defaultLabels?: Record<string, string[]>
  ): void => {
    const module = modules.value.find((m) => m.id === moduleId)
    if (!module) return

    // 프리셋별 기본 라벨
    const labels: Record<string, string[][]> = {
      '2col-simple': [
        ['항목', '내용'],
        ['항목', '내용'],
        ['항목', '내용'],
      ],
      '3col-simple': [
        ['항목', '내용', '내용'],
        ['항목', '내용', '내용'],
        ['항목', '내용', '내용'],
      ],
      'schedule': [
        ['시간', '내용', '비고'],
        ['10:00', '', ''],
        ['11:00', '', ''],
        ['12:00', '', ''],
      ],
      'price': [
        ['구분', '가격', '비고'],
        ['항목1', '', ''],
        ['항목2', '', ''],
        ['항목3', '', ''],
      ],
    }

    const presetLabels = labels[presetId] || []

    // 새 테이블 셀 생성
    const newCells: TableCell[][] = []
    for (let r = 0; r < rows; r++) {
      const row: TableCell[] = []
      for (let c = 0; c < cols; c++) {
        const cellType = structure[r]?.[c] || 'td'
        const content = presetLabels[r]?.[c] || ''
        row.push({
          id: generateUniqueId('cell'),
          type: cellType,
          content,
          colspan: 1,
          rowspan: 1,
        })
      }
      newCells.push(row)
    }

    module.properties.tableCells = newCells
    module.properties.tablePresetId = presetId
    module.properties.tableColWidths = Array.from({ length: cols }, () => '')
    // 열 공통 정렬: 1열 가운데, 나머지 왼쪽
    module.properties.tableColAligns = Array.from({ length: cols }, (_, i) => (i === 0 ? 'center' : 'left'))
    triggerRef(modules)
  }

