/**
 * Quill HTML 후처리 유틸리티
 * - RGB → HEX 색상 변환
 * - 블록 요소에 margin: 0, padding: 0 추가
 */

/**
 * RGB 문자열을 HEX로 변환
 */
const rgbToHex = (rgb: string): string => {
  const match = rgb.match(/^rgb\((\d+),\s*(\d+),\s*(\d+)\)$/)
  if (!match) return rgb

  const r = Number.parseInt(match[1])
  const g = Number.parseInt(match[2])
  const b = Number.parseInt(match[3])

  const toHex = (n: number) => {
    const hex = n.toString(16)
    return hex.length === 1 ? '0' + hex : hex
  }

  return `#${toHex(r)}${toHex(g)}${toHex(b)}`
}

/**
 * RGBA 문자열을 HEX로 변환
 */
const rgbaToHex = (rgba: string): string => {
  const match = rgba.match(/^rgba\((\d+),\s*(\d+),\s*(\d+),\s*([0-9.]+)\)$/)
  if (!match) return rgba

  const r = Number.parseInt(match[1])
  const g = Number.parseInt(match[2])
  const b = Number.parseInt(match[3])
  const a = Number.parseFloat(match[4])

  const toHex = (n: number) => {
    const hex = n.toString(16)
    return hex.length === 1 ? '0' + hex : hex
  }

  // 알파가 1이면 알파 채널 생략
  if (a === 1) {
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`
  }

  const alpha = Math.round(a * 255)
  return `#${toHex(r)}${toHex(g)}${toHex(b)}${toHex(alpha)}`
}

/**
 * HTML 내 모든 RGB/RGBA를 HEX로 변환
 */
export const convertRgbToHex = (html: string): string => {
  if (!html) return ''

  // RGBA 패턴 먼저 처리 (RGB보다 먼저 매칭되어야 함)
  let result = html.replace(/rgba\((\d+),\s*(\d+),\s*(\d+),\s*([0-9.]+)\)/g, (match) => {
    return rgbaToHex(match)
  })

  // RGB 패턴 처리
  result = result.replace(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/g, (match) => {
    return rgbToHex(match)
  })

  return result
}

/**
 * 블록 요소에 margin: 0, padding: 0, word-wrap: break-word, word-break: break-all 추가
 * 처리 대상: p, h1, h2, h3
 * word-wrap: break-word는 긴 텍스트가 컨테이너를 넘어갈 때 자동 줄바꿈
 * word-break: break-all은 긴 텍스트(이모지, 특수문자 포함)가 컨테이너를 넘지 않도록 강제 줄바꿈
 */
/**
 * 문단의 overflow-wrap 값 결정.
 * '단어기준(word-break: keep-all)' 문단은 공백 없는 긴 토큰(긴 한글/영문/URL)을 끊지 못해
 * 컬럼의 min-content 너비가 커진다. 2단 모듈(04·05·06 등)의 inline-block 컬럼이 50%를 넘치며
 * 레이아웃이 깨지므로, keep-all일 때는 break-word 대신 anywhere를 쓴다.
 * (anywhere는 break-word와 달리 min-content 폭도 줄여 긴 토큰만 강제 분할 → 단어 단위 줄바꿈은 유지)
 */
const overflowWrapFor = (style: string): string =>
  /word-break:\s*keep-all/.test(style) ? 'anywhere' : 'break-word'

export const addZeroSpacingToBlocks = (html: string): string => {
  if (!html) return ''

  // 기본 텍스트 스타일 (줄바꿈 관련) — 행간 미지정 시 기본 1.7
  const baseTextStyle = 'margin: 0; padding: 0; line-height: 1.7; word-wrap: break-word; overflow-wrap: break-word;'

  // p, h1, h2, h3 태그 일괄 처리
  const tagPattern = /<(p|h[1-3])(\s+([^>]*))?>/gi

  html = html.replace(tagPattern, (match, tagName, attributes, attrContent) => {
    // 속성이 없는 경우
    if (!attributes) {
      return `<${tagName} style="${baseTextStyle}">`
    }

    // style 속성 추출
    const styleMatch = attrContent.match(/style="([^"]*)"/)

    if (styleMatch) {
      // 이미 style이 있는 경우
      let existingStyle = styleMatch[1].trim()

      // margin이 없으면 추가
      if (!existingStyle.includes('margin')) {
        existingStyle += '; margin: 0'
      }

      // padding이 없으면 추가
      if (!existingStyle.includes('padding')) {
        existingStyle += '; padding: 0'
      }

      // word-wrap이 없으면 추가 (자동 줄바꿈)
      if (!existingStyle.includes('word-wrap')) {
        existingStyle += `; word-wrap: break-word; overflow-wrap: ${overflowWrapFor(existingStyle)}`
      }

      // word-break가 없으면 추가 (강제 줄바꿈 - 이모지, 특수문자 포함 긴 텍스트 처리)
      if (!existingStyle.includes('word-break')) {
        existingStyle += '; word-break: break-all'
      }

      // line-height가 없으면 기본값 추가 (에디터에서 행간 미지정 시 1.7)
      if (!existingStyle.includes('line-height')) {
        existingStyle += '; line-height: 1.7'
      }

      // 세미콜론 정리 (중복 제거, 앞뒤 공백 제거)
      existingStyle = existingStyle.replace(/;+/g, ';').replace(/^;\s*/, '').replace(/;\s*$/, '')

      // style 교체
      const newAttributes = attrContent.replace(/style="[^"]*"/, `style="${existingStyle};"`)
      return `<${tagName} ${newAttributes}>`
    } else {
      // style이 없는 경우 추가
      return `<${tagName} ${attrContent} style="${baseTextStyle}">`
    }
  })

  return html
}

/**
 * 빈 줄(엔터로 추가된 여백)을 이메일 호환 형태로 변환
 * Quill에서 엔터를 누르면 <p><br></p> 형태가 생성됨
 * 이를 높이가 있는 빈 줄로 변환하여 이메일에서도 여백이 표시되도록 함
 */
export const convertEmptyLinesToSpacing = (html: string): string => {
  if (!html) return ''

  // <p><br></p> 패턴을 높이가 있는 빈 줄로 변환
  // 이메일 클라이언트에서 빈 <p> 태그는 무시될 수 있으므로 &nbsp;와 line-height로 높이 확보
  html = html.replace(
    /<p([^>]*)><br\s*\/?><\/p>/gi,
    (match, attributes) => {
      // 기존 style 속성 확인
      const styleMatch = attributes.match(/style="([^"]*)"/)
      let style = styleMatch ? styleMatch[1].trim() : ''

      // 기본 스타일 추가
      if (!style.includes('margin')) {
        style = style ? `${style}; margin: 0` : 'margin: 0'
      }
      if (!style.includes('padding')) {
        style += '; padding: 0'
      }
      if (!style.includes('line-height')) {
        style += '; line-height: 1.7'
      }
      if (!style.includes('min-height')) {
        style += '; min-height: 1.5em'
      }

      // 빈 줄에 &nbsp; 추가하여 높이 확보
      const otherAttrs = attributes.replace(/style="[^"]*"/gi, '').trim()
      return `<p${otherAttrs ? ' ' + otherAttrs : ''} style="${style};">&nbsp;</p>`
    }
  )

  // 빈 <p></p> 패턴도 처리
  html = html.replace(
    /<p([^>]*)><\/p>/gi,
    (match, attributes) => {
      const styleMatch = attributes.match(/style="([^"]*)"/)
      let style = styleMatch ? styleMatch[1].trim() : ''

      if (!style.includes('margin')) {
        style = style ? `${style}; margin: 0` : 'margin: 0'
      }
      if (!style.includes('padding')) {
        style += '; padding: 0'
      }
      if (!style.includes('line-height')) {
        style += '; line-height: 1.7'
      }
      if (!style.includes('min-height')) {
        style += '; min-height: 1.5em'
      }

      const otherAttrs = attributes.replace(/style="[^"]*"/gi, '').trim()
      return `<p${otherAttrs ? ' ' + otherAttrs : ''} style="${style};">&nbsp;</p>`
    }
  )

  return html
}

/**
 * Quill 정렬 클래스를 인라인 스타일로 변환
 * - ql-align-center → text-align: center
 * - ql-align-right → text-align: right
 * - ql-align-justify → text-align: justify
 */
export const convertQuillAlignToInline = (html: string): string => {
  if (!html) return ''

  // 정렬 클래스 매핑
  const alignMap: Record<string, string> = {
    'ql-align-center': 'center',
    'ql-align-right': 'right',
    'ql-align-justify': 'justify',
  }

  // 각 정렬 클래스 처리
  Object.entries(alignMap).forEach(([className, alignValue]) => {
    // class="ql-align-xxx" 또는 class="other ql-align-xxx" 패턴 찾기
    const classRegex = new RegExp(
      `(<(?:p|h1|h2|h3)[^>]*?)class="([^"]*?${className}[^"]*?)"([^>]*?>)`,
      'gi',
    )

    html = html.replace(classRegex, (match, before, classAttr, after) => {
      // 기존 클래스에서 정렬 클래스 제거
      let newClasses = classAttr.replace(className, '').trim()
      newClasses = newClasses.replace(/\s+/g, ' ') // 중복 공백 제거

      // style 속성 확인
      const styleMatch = (before + after).match(/style="([^"]*)"/)
      let style = styleMatch ? styleMatch[1].trim() : ''

      // text-align 추가 (기존에 없는 경우에만)
      if (!style.includes('text-align')) {
        style = style ? `${style}; text-align: ${alignValue}` : `text-align: ${alignValue}`
      }

      // class 속성 재구성 (빈 값이면 제거)
      const classStr = newClasses ? ` class="${newClasses}"` : ''

      // style 속성이 이미 있으면 제거하고 새로 추가
      const cleanBefore = before.replace(/\s*style="[^"]*"/gi, '').trim()
      const cleanAfter = after.replace(/\s*style="[^"]*"/gi, '').trim()

      // 최종 태그 재구성
      return `${cleanBefore}${classStr} style="${style};"${cleanAfter}`
    })
  })

  // 빈 class 속성 제거
  html = html.replace(/\s*class=""\s*/g, ' ')

  return html
}

/**
 * Quill 2의 리스트 출력을 이메일 호환 시맨틱 리스트로 변환한다.
 * - Quill 2는 글머리/번호 목록을 모두 <ol><li data-list="bullet|ordered">로 출력하고
 *   마커(•, 1.)를 Quill 전용 CSS로만 그리므로, 에디터 밖(미리보기·이메일)에선 마커가 보이지 않는다.
 * - data-list 타입에 따라 <ul>/<ol>로 재구성하고 인라인 list-style을 부여해 어디서나 마커가 보이도록 한다.
 * - 에디터 전용 마커 요소(<span class="ql-ui">)는 제거한다.
 */
export const convertQuillListsToEmailHtml = (html: string): string => {
  if (!html) return ''
  // DOM이 없거나 변환 대상이 없으면 그대로 반환
  if (typeof document === 'undefined') return html
  if (!html.includes('data-list') && !html.includes('ql-ui')) return html

  const container = document.createElement('div')
  container.innerHTML = html

  // 에디터 전용 마커 요소 제거
  container.querySelectorAll('span.ql-ui').forEach((n) => n.remove())

  // Quill 리스트 래퍼(주로 <ol>)를 항목 타입별 <ul>/<ol>로 재구성
  container.querySelectorAll('ol, ul').forEach((listEl) => {
    const items = Array.from(listEl.children).filter((c) => c.tagName === 'LI') as HTMLElement[]
    if (!items.length) return

    const frag = document.createDocumentFragment()
    let curType: 'ordered' | 'bullet' | null = null
    let curList: HTMLElement | null = null

    items.forEach((li) => {
      const type = li.dataset.list === 'ordered' ? 'ordered' : 'bullet'
      if (type !== curType || !curList) {
        curType = type
        curList = document.createElement(type === 'ordered' ? 'ol' : 'ul')
        curList.setAttribute(
          'style',
          `margin:0; padding-left:24px; list-style-type:${type === 'ordered' ? 'decimal' : 'disc'};`,
        )
        frag.appendChild(curList)
      }
      delete li.dataset.list
      li.setAttribute('style', 'margin:0;')
      curList.appendChild(li)
    })

    listEl.replaceWith(frag)
  })

  return container.innerHTML
}

/**
 * 타이핑된 공백이 &nbsp;(U+00A0, 줄바꿈 불가 공백)로 저장되면
 * word-break(단어기준 keep-all / 글자기준 break-all)가 끊을 지점을 찾지 못한다.
 * → 단어 사이 띄어쓰기를 '일반 공백'으로 되돌려 줄바꿈 규칙이 실제로 동작하게 한다.
 *
 * 단, 빈 줄 높이 확보용 스페이서(요소 내용이 &nbsp; 하나뿐인 <p>&nbsp;</p> = ">&nbsp;<")는
 * 그대로 보존한다. (convertEmptyLinesToSpacing이 만드는 여백이 사라지지 않도록)
 */
export const normalizeNbspForWordBreak = (html: string): string => {
  if (!html) return ''
  // 리터럴 U+00A0(타이핑된 공백)은 항상 일반 공백으로
  let out = html.replace(/ /g, ' ')
  // &nbsp; 엔티티: '요소 내용이 nbsp 하나뿐인' 스페이서(>&nbsp;<)만 보존, 나머지는 공백으로
  out = out.replace(/&nbsp;/g, (m, offset: number, s: string) =>
    s[offset - 1] === '>' && s[offset + m.length] === '<' ? m : ' ',
  )
  return out
}

/**
 * Quill HTML 통합 처리 함수 (에디터 저장·미리보기 공용)
 * 1. RGB → HEX 변환
 * 2. 띄어쓰기(&nbsp;) → 일반 공백 정규화 (word-break 정상 동작)
 * 3. 빈 줄을 이메일 호환 형태로 변환
 * 4. 블록 요소에 margin: 0, padding: 0 추가
 * 5. Quill 정렬 클래스를 인라인 스타일로 변환
 *
 * 참고: 리스트(<ol><li data-list>)는 Quill 네이티브 형식을 그대로 유지한다.
 * 에디터와 미리보기(ModuleRenderer CSS)가 data-list 기준으로 마커를 렌더링하기 때문이다.
 * 이메일용 <ul>/<ol> 변환은 최종 내보내기(generateHtml)에서 convertQuillListsToEmailHtml로만 수행한다.
 */
export const processQuillHtml = (html: string): string => {
  if (!html) return ''

  // 1. RGB → HEX 변환
  html = convertRgbToHex(html)

  // 2. 띄어쓰기(&nbsp;) → 일반 공백 (빈 줄 스페이서 추가 '전'에 실행)
  html = normalizeNbspForWordBreak(html)

  // 3. 빈 줄(엔터 여백)을 이메일 호환 형태로 변환
  html = convertEmptyLinesToSpacing(html)

  // 3. 블록 요소에 margin: 0, padding: 0 추가
  html = addZeroSpacingToBlocks(html)

  // 4. Quill 정렬 클래스를 인라인 스타일로 변환
  html = convertQuillAlignToInline(html)

  return html
}
